int rtw88_write32(struct rtw_dev *rtwdev, uint32_t addr, uint32_t val);

static inline void
rtw_write_rf(struct rtw_dev *rtwdev, enum rtw_rf_path rf_path,
             u32 addr, u32 mask, u32 data);


#define RFREG_MASK 0xfffff

void rtw_phy_cfg_rf(struct rtw_dev *rtwdev, const struct rtw_table *tbl,
                    u32 addr, u32 data)
{
//        if (addr == 0xffe) {
//                msleep(50);
//        } else if (addr == 0xfe) {
//                usleep_range(100, 110);
//        } else {
//                rtw_write_rf(rtwdev, tbl->rf_path, addr, RFREG_MASK, data);
//                udelay(1);
//        }

        if (addr == 0xffe) {
                DELAY(50 * 1000);
        } else if (addr == 0xfe) {
                DELAY(110);
        } else {
                rtw_write_rf(rtwdev, tbl->rf_path, addr, RFREG_MASK, data);
                DELAY(1);
        }
}

void rtw_phy_cfg_agc(struct rtw_dev *rtwdev, const struct rtw_table *tbl,
                     u32 addr, u32 data)
{
        rtw_write32(rtwdev, addr, data);
}


void rtw_phy_cfg_mac(struct rtw_dev *rtwdev, const struct rtw_table *tbl,
                     u32 addr, u32 data)
{
        rtw_write8(rtwdev, addr, data);
}

void rtw_phy_cfg_bb(struct rtw_dev *rtwdev, const struct rtw_table *tbl,
                    u32 addr, u32 data)
{
//        if (addr == 0xfe)
//                msleep(50);
//        else if (addr == 0xfd)
//                mdelay(5);
//        else if (addr == 0xfc)
//                mdelay(1);
//        else if (addr == 0xfb)
//                usleep_range(50, 60);
//        else if (addr == 0xfa)
//                udelay(5);
//        else if (addr == 0xf9)
//                udelay(1);
//        else
//                rtw_write32(rtwdev, addr, data);

        if (addr == 0xfe)
                DELAY(50 * 1000);
        else if (addr == 0xfd)
                DELAY(5 * 1000);
        else if (addr == 0xfc)
                DELAY(1 * 1000);
        else if (addr == 0xfb)
                DELAY(60);
        else if (addr == 0xfa)
                DELAY(5);
        else if (addr == 0xf9)
                DELAY(1);
        else
                rtw_write32(rtwdev, addr, data);
}

void rtw_parse_tbl_phy_cond(struct rtw_dev *rtwdev, const struct rtw_table *tbl);

#define RTW_DECL_TABLE_PHY_COND_CORE(name, cfg, path)   \
const struct rtw_table name ## _tbl = {                 \
        .data = name,                                   \
        .size = ARRAY_SIZE(name),                       \
        .parse = rtw_parse_tbl_phy_cond,                \
        .do_cfg = cfg,                                  \
        .rf_path = path,                                \
}

#define RTW_DECL_TABLE_PHY_COND(name, cfg)              \
        RTW_DECL_TABLE_PHY_COND_CORE(name, cfg, 0)

#define RTW_DECL_TABLE_RF_RADIO(name, path)             \
    RTW_DECL_TABLE_PHY_COND_CORE(name, rtw_phy_cfg_rf, RF_PATH_ ## path)

