struct rtw_phy_cond {
#ifdef __LITTLE_ENDIAN
        u32 rfe:8;
        u32 intf:4;
        u32 pkg:4;
        u32 plat:4;
        u32 intf_rsvd:4;
        u32 cut:4;
        u32 branch:2;
        u32 neg:1;
        u32 pos:1;
#else
        u32 pos:1;
        u32 neg:1;
        u32 branch:2;
        u32 cut:4;
        u32 intf_rsvd:4;
        u32 plat:4;
        u32 pkg:4;
        u32 intf:4;
        u32 rfe:8;
#endif
        /* for intf:4 */
        #define INTF_PCIE       BIT(0)
        #define INTF_USB        BIT(1)
        #define INTF_SDIO       BIT(2)
        /* for branch:2 */
        #define BRANCH_IF       0
        #define BRANCH_ELIF     1
        #define BRANCH_ELSE     2
        #define BRANCH_ENDIF    3
};

