struct rtw_5g_ht_1s_pwr_idx_diff {
#ifdef __LITTLE_ENDIAN
        s8 ofdm:4;
        s8 bw20:4;
#else
        s8 bw20:4;
        s8 ofdm:4;
#endif
} __packed;

struct rtw_5g_ht_ns_pwr_idx_diff {
#ifdef __LITTLE_ENDIAN
        s8 bw20:4;
        s8 bw40:4;
#else
        s8 bw40:4;
        s8 bw20:4;
#endif
} __packed;

struct rtw_5g_ofdm_ns_pwr_idx_diff {
#ifdef __LITTLE_ENDIAN
        s8 ofdm_3s:4;
        s8 ofdm_2s:4;
        s8 ofdm_4s:4;
        s8 res:4;
#else
        s8 res:4;
        s8 ofdm_4s:4;
        s8 ofdm_2s:4;
        s8 ofdm_3s:4;
#endif
} __packed;

struct rtw_5g_vht_ns_pwr_idx_diff {
#ifdef __LITTLE_ENDIAN
        s8 bw160:4;
        s8 bw80:4;
#else
        s8 bw80:4;
        s8 bw160:4;
#endif
} __packed;

struct rtw_5g_txpwr_idx {
        u8 bw40_base[14];
        struct rtw_5g_ht_1s_pwr_idx_diff ht_1s_diff;
        struct rtw_5g_ht_ns_pwr_idx_diff ht_2s_diff;
        struct rtw_5g_ht_ns_pwr_idx_diff ht_3s_diff;
        struct rtw_5g_ht_ns_pwr_idx_diff ht_4s_diff;
        struct rtw_5g_ofdm_ns_pwr_idx_diff ofdm_diff;
        struct rtw_5g_vht_ns_pwr_idx_diff vht_1s_diff;
        struct rtw_5g_vht_ns_pwr_idx_diff vht_2s_diff;
        struct rtw_5g_vht_ns_pwr_idx_diff vht_3s_diff;
        struct rtw_5g_vht_ns_pwr_idx_diff vht_4s_diff;
};

/* the power index is represented by differences, which cck-1s & ht40-1s are
 * the base values, so for 1s's differences, there are only ht20 & ofdm
 */
struct rtw_2g_1s_pwr_idx_diff {
#ifdef __LITTLE_ENDIAN
        s8 ofdm:4;
        s8 bw20:4;
#else
        s8 bw20:4;
        s8 ofdm:4;
#endif
} __packed;

struct rtw_2g_ns_pwr_idx_diff {
#ifdef __LITTLE_ENDIAN
        s8 bw20:4;
        s8 bw40:4;
        s8 cck:4;
        s8 ofdm:4;
#else
        s8 ofdm:4;
        s8 cck:4;
        s8 bw40:4;
        s8 bw20:4;
#endif
} __packed;

struct rtw_2g_txpwr_idx {
        u8 cck_base[6];
        u8 bw40_base[5];
        struct rtw_2g_1s_pwr_idx_diff ht_1s_diff;
        struct rtw_2g_ns_pwr_idx_diff ht_2s_diff;
        struct rtw_2g_ns_pwr_idx_diff ht_3s_diff;
        struct rtw_2g_ns_pwr_idx_diff ht_4s_diff;
};

struct rtw_txpwr_idx {
        struct rtw_2g_txpwr_idx pwr_idx_2g;
        struct rtw_5g_txpwr_idx pwr_idx_5g;
};


struct rtw8822bu_efuse {
        u8 res4[4];                     /* 0xd0 */
        u8 usb_optional_function;
        u8 res5[0x1e];
        u8 res6[2];
        u8 serial[0x0b];                /* 0xf5 */
        u8 vid;                         /* 0x100 */
        u8 res7;
        u8 pid;
        u8 res8[4];
        u8 mac_addr[ETH_ALEN];          /* 0x107 */
        u8 res9[2];
        u8 vendor_name[0x07];
        u8 res10[2];
        u8 device_name[0x14];
        u8 res11[0xcf];
        u8 package_type;                /* 0x1fb */
        u8 res12[0x4];
};

struct rtw8822be_efuse {
        u8 mac_addr[ETH_ALEN];          /* 0xd0 */
        u8 vender_id[2];
        u8 device_id[2];
        u8 sub_vender_id[2];
        u8 sub_device_id[2];
        u8 pmc[2];
        u8 exp_device_cap[2];
        u8 msi_cap;
        u8 ltr_cap;                     /* 0xe3 */
        u8 exp_link_control[2];
        u8 link_cap[4];
        u8 link_control[2];
        u8 serial_number[8];
        u8 res0:2;                      /* 0xf4 */
        u8 ltr_en:1;
        u8 res1:2;
        u8 obff:2;
        u8 res2:3;
        u8 obff_cap:2;
        u8 res3:4;
        u8 res4[3];
        u8 class_code[3];
        u8 pci_pm_L1_2_supp:1;
        u8 pci_pm_L1_1_supp:1;
        u8 aspm_pm_L1_2_supp:1;
        u8 aspm_pm_L1_1_supp:1;
        u8 L1_pm_substates_supp:1;
        u8 res5:3;
        u8 port_common_mode_restore_time;
        u8 port_t_power_on_scale:2;
        u8 res6:1;
        u8 port_t_power_on_value:5;
        u8 res7;
};

struct rtw8822bs_efuse {
        u8 res4[0x4a];                  /* 0xd0 */
        u8 mac_addr[ETH_ALEN];          /* 0x11a */
} __packed;

struct rtw8822b_efuse {
        __le16 rtl_id;
        u8 res0[4];
        u8 usb_mode;
        u8 res1[0x09];

        /* power index for four RF paths */
        struct rtw_txpwr_idx txpwr_idx_table[4];

        u8 channel_plan;                /* 0xb8 */
        u8 xtal_k;
        u8 thermal_meter;
        u8 iqk_lck;
        u8 pa_type;                     /* 0xbc */
        u8 lna_type_2g[2];              /* 0xbd */
        u8 lna_type_5g[2];
        u8 rf_board_option;
        u8 rf_feature_option;
        u8 rf_bt_setting;
        u8 eeprom_version;
        u8 eeprom_customer_id;
        u8 tx_bb_swing_setting_2g;
        u8 tx_bb_swing_setting_5g;
        u8 tx_pwr_calibrate_rate;
        u8 rf_antenna_option;           /* 0xc9 */
        u8 rfe_option;
        u8 country_code[2];
        u8 res[3];
        union {
                struct rtw8822be_efuse e;
                struct rtw8822bu_efuse u;
                struct rtw8822bs_efuse s;
        };
};


