enum rtw_bb_path {
	BB_PATH_A = BIT(0),
	BB_PATH_B = BIT(1),
	BB_PATH_C = BIT(2),
	BB_PATH_D = BIT(3),

	BB_PATH_AB = (BB_PATH_A | BB_PATH_B),
	BB_PATH_AC = (BB_PATH_A | BB_PATH_C),
	BB_PATH_AD = (BB_PATH_A | BB_PATH_D),
	BB_PATH_BC = (BB_PATH_B | BB_PATH_C),
	BB_PATH_BD = (BB_PATH_B | BB_PATH_D),
	BB_PATH_CD = (BB_PATH_C | BB_PATH_D),

	BB_PATH_ABC = (BB_PATH_A | BB_PATH_B | BB_PATH_C),
	BB_PATH_ABD = (BB_PATH_A | BB_PATH_B | BB_PATH_D),
	BB_PATH_ACD = (BB_PATH_A | BB_PATH_C | BB_PATH_D),
	BB_PATH_BCD = (BB_PATH_B | BB_PATH_C | BB_PATH_D),

	BB_PATH_ABCD = (BB_PATH_A | BB_PATH_B | BB_PATH_C | BB_PATH_D),
};

struct rtw_path_div {
        enum rtw_bb_path current_tx_path;
        u32 path_a_sum;
        u32 path_b_sum;
        u16 path_a_cnt;
        u16 path_b_cnt;
};


enum rtw_rf_type {
	RF_1T1R			= 0,
	RF_1T2R			= 1,
	RF_2T2R			= 2,
	RF_2T3R			= 3,
	RF_2T4R			= 4,
	RF_3T3R			= 5,
	RF_3T4R			= 6,
	RF_4T4R			= 7,
	RF_TYPE_MAX,
};


struct rtw88_efuse {
	uint32_t size;
	uint32_t physical_size;
	uint32_t logical_size;
	uint32_t protect_size;
//
	uint8_t addr[ETH_ALEN];
	uint8_t channel_plan;
	uint8_t country_code[2];
	uint8_t rf_board_option;
	uint8_t rfe_option;
	uint8_t power_track_type;
	uint8_t thermal_meter[RTW_RF_PATH_MAX];
	uint8_t thermal_meter_k;
	uint8_t crystal_cap;
	uint8_t ant_div_cfg;
	uint8_t ant_div_type;
	uint8_t regd;
	uint8_t afe;

	uint8_t lna_type_2g;
	uint8_t lna_type_5g;
	uint8_t glna_type;
	uint8_t alna_type;
	bool ext_lna_2g;
	bool ext_lna_5g;
	uint8_t pa_type_2g;
	uint8_t pa_type_5g;
	uint8_t gpa_type;
	uint8_t apa_type;
	bool ext_pa_2g;
	bool ext_pa_5g;
	uint8_t tx_bb_swing_setting_2g;
	uint8_t tx_bb_swing_setting_5g;

	bool btcoex;
	/* bt share antenna with wifi */
	bool share_ant;
	uint8_t bt_setting;

	u8 usb_mode_switch;

	struct {
		uint8_t hci;
		uint8_t bw;
		uint8_t ptcl;
		uint8_t nss;
		uint8_t ant_num;
	} hw_cap;

	struct rtw_txpwr_idx txpwr_idx_table[4];
};

