static u8 tbl_to_dec_pwr_by_rate(struct rtw_dev *rtwdev, u32 hex, u8 i)
{
        if (rtwdev->chip->is_pwr_by_rate_dec)
                return bcd_to_dec_pwr_by_rate(hex, i);

        return (hex >> (i * 8)) & 0xFF;
}


