inline void
rtw88_write8_set(struct rtw_dev *rtwdev, uint32_t addr, uint8_t bit)
{
	uint8_t val;

	val = rtw88_read8(rtwdev, addr);
	rtw88_write8(rtwdev, addr, val | bit);
}

