{
        SET_PKT_H2C_CATEGORY(h2c_pkt, H2C_PKT_CATEGORY);
        SET_PKT_H2C_CMD_ID(h2c_pkt, H2C_PKT_CMD_ID);
        SET_PKT_H2C_SUB_CMD_ID(h2c_pkt, sub_id);
}

